<?php
declare(strict_types=1);
function apForm(string $action): string{return '<form method="post">'.csrf().'<input type="hidden" name="action" value="'.e($action).'">';}
function apUploadForm(string $action): string{return '<form method="post" enctype="multipart/form-data">'.csrf().'<input type="hidden" name="action" value="'.e($action).'">';}
function apField(string $label,string $name,string $value='',int $max=200,string $type='text'): void {if(isset($_POST[$name])&&is_string($_POST[$name]))$value=$_POST[$name];echo '<label>'.e($label).'<input name="'.e($name).'" type="'.$type.'" maxlength="'.$max.'" value="'.e($value).'" required></label>';}
function applicationFormFields(array $data,string $privacy): void {
    foreach([['Full legal name','name',120],['Contact phone','phone',30],['City / town','city',100],['Highest completed qualification','qualification',300],['Completion year','completion_year',4]] as [$label,$key,$max])apField($label,$key,(string)($data[$key]??''),$max);
    $note=is_string($_POST['note']??null)?$_POST['note']:($data['note']??'');echo '<label>Additional information (optional; no identity numbers or medical information)<textarea name="note" maxlength="1500" rows="4">'.e($note).'</textarea></label><details open><summary>Institute application privacy notice</summary><p>'.nl2br(e($privacy)).'</p></details><label class="ap-check"><input type="checkbox" name="consent" value="yes" required> I have read the notice and consent to processing this application. The details are accurate, and I understand admission requires eligibility verification and office approval. I will contact the office about any required guardian consent.</label>';
}
?>
